# Check for command injection vulnerabilities in subprocess calls
import subprocess

def safe_subprocess_call(command):
    try:
        result = subprocess.run(command, check=True, stderr=subprocess.PIPE)
        print("Command executed successfully:", result)
    except subprocess.CalledProcessError as e:
        print("Error occurred:", e.stderr.decode())

# Example usage
safe_subprocess_call(["echo", "Hello, World!"])
